; f4_wtc_m: WTC per block: DMA bursts between blocks and across a boundary
; Generated by validation/v35s/wtc.py emit (python -m validation.v35s.wtc emit): the bytes
; are the generator's; the image also holds the fill, the sleds and the stubs (wtc.py
; base_image) in the pages each side of every 128K boundary.
    DB 0FAh    ; DI
    DB 0B8h, 00h, 00h    ; MOV AW, 0000h
    DB 8Eh, 0D0h    ; MOV SS, AW
    DB 0BCh, 00h, 0Fh    ; MOV SP, 0F00h
    DB 8Eh, 0D8h    ; MOV DS0, AW
    DB 0B8h, 00h, 0F0h    ; MOV AW, F000h
    DB 8Eh, 0C0h    ; MOV DS1, AW
    DB 26h, 0A1h, 0E8h, 0FFh    ; MOV AW, DS1:[FFE8h]   ; WTC at reset
    DB 2Eh, 0A3h, 00h, 0Fh    ; MOV PS:[0F00h], AW
    DB 26h, 0A0h, 0E1h, 0FFh    ; MOV AL, DS1:[FFE1h]   ; RFM at reset
    DB 2Eh, 0A2h, 02h, 0Fh    ; MOV PS:[0F02h], AL
; ---- window 0: WTC 0000h PMC1 00h RFM ECh sub_dma 
    DB 26h, 0C6h, 06h, 0E1h, 0FFh, 0ECh    ; MOV byte DS1:[FFE1h], ECh
    DB 26h, 0C7h, 06h, 0E8h, 0FFh, 00h, 00h    ; MOV word DS1:[FFE8h], 0000h
    DB 0BAh, 40h, 0FEh    ; MOV DW, FE40h
    DB 0B8h, 00h, 00h    ; MOV AW, 0000h
    DB 0EFh    ; OUT DW, AW
    DB 0E8h, 02h, 01h    ; CALL sub_dma
    DB 0BAh, 42h, 0FEh    ; MOV DW, FE42h
    DB 0B8h, 00h, 00h    ; MOV AW, 0000h
    DB 0EFh    ; OUT DW, AW
; ---- window 1: WTC 4924h PMC1 00h RFM ECh sub_dma 
    DB 26h, 0C7h, 06h, 0E8h, 0FFh, 24h, 49h    ; MOV word DS1:[FFE8h], 4924h
    DB 0BAh, 40h, 0FEh    ; MOV DW, FE40h
    DB 0B8h, 01h, 00h    ; MOV AW, 0001h
    DB 0EFh    ; OUT DW, AW
    DB 0E8h, 0EAh, 00h    ; CALL sub_dma
    DB 0BAh, 42h, 0FEh    ; MOV DW, FE42h
    DB 0B8h, 01h, 00h    ; MOV AW, 0001h
    DB 0EFh    ; OUT DW, AW
; ---- window 2: WTC A540h PMC1 00h RFM ECh sub_dma 
    DB 26h, 0C7h, 06h, 0E8h, 0FFh, 40h, 0A5h    ; MOV word DS1:[FFE8h], A540h
    DB 0BAh, 40h, 0FEh    ; MOV DW, FE40h
    DB 0B8h, 02h, 00h    ; MOV AW, 0002h
    DB 0EFh    ; OUT DW, AW
    DB 0E8h, 0D2h, 00h    ; CALL sub_dma
    DB 0BAh, 42h, 0FEh    ; MOV DW, FE42h
    DB 0B8h, 02h, 00h    ; MOV AW, 0002h
    DB 0EFh    ; OUT DW, AW
; ---- window 3: WTC 0002h PMC1 00h RFM ECh sub_dma 
    DB 26h, 0C7h, 06h, 0E8h, 0FFh, 02h, 00h    ; MOV word DS1:[FFE8h], 0002h
    DB 0BAh, 40h, 0FEh    ; MOV DW, FE40h
    DB 0B8h, 03h, 00h    ; MOV AW, 0003h
    DB 0EFh    ; OUT DW, AW
    DB 0E8h, 0BAh, 00h    ; CALL sub_dma
    DB 0BAh, 42h, 0FEh    ; MOV DW, FE42h
    DB 0B8h, 03h, 00h    ; MOV AW, 0003h
    DB 0EFh    ; OUT DW, AW
; ---- window 4: WTC 0008h PMC1 00h RFM ECh sub_dma 
    DB 26h, 0C7h, 06h, 0E8h, 0FFh, 08h, 00h    ; MOV word DS1:[FFE8h], 0008h
    DB 0BAh, 40h, 0FEh    ; MOV DW, FE40h
    DB 0B8h, 04h, 00h    ; MOV AW, 0004h
    DB 0EFh    ; OUT DW, AW
    DB 0E8h, 0A2h, 00h    ; CALL sub_dma
    DB 0BAh, 42h, 0FEh    ; MOV DW, FE42h
    DB 0B8h, 04h, 00h    ; MOV AW, 0004h
    DB 0EFh    ; OUT DW, AW
; ---- window 5: WTC 0020h PMC1 00h RFM ECh sub_dma 
    DB 26h, 0C7h, 06h, 0E8h, 0FFh, 20h, 00h    ; MOV word DS1:[FFE8h], 0020h
    DB 0BAh, 40h, 0FEh    ; MOV DW, FE40h
    DB 0B8h, 05h, 00h    ; MOV AW, 0005h
    DB 0EFh    ; OUT DW, AW
    DB 0E8h, 8Ah, 00h    ; CALL sub_dma
    DB 0BAh, 42h, 0FEh    ; MOV DW, FE42h
    DB 0B8h, 05h, 00h    ; MOV AW, 0005h
    DB 0EFh    ; OUT DW, AW
; ---- window 6: WTC 0080h PMC1 00h RFM ECh sub_dma 
    DB 26h, 0C7h, 06h, 0E8h, 0FFh, 80h, 00h    ; MOV word DS1:[FFE8h], 0080h
    DB 0BAh, 40h, 0FEh    ; MOV DW, FE40h
    DB 0B8h, 06h, 00h    ; MOV AW, 0006h
    DB 0EFh    ; OUT DW, AW
    DB 0E8h, 72h, 00h    ; CALL sub_dma
    DB 0BAh, 42h, 0FEh    ; MOV DW, FE42h
    DB 0B8h, 06h, 00h    ; MOV AW, 0006h
    DB 0EFh    ; OUT DW, AW
; ---- window 7: WTC 0200h PMC1 00h RFM ECh sub_dma 
    DB 26h, 0C7h, 06h, 0E8h, 0FFh, 00h, 02h    ; MOV word DS1:[FFE8h], 0200h
    DB 0BAh, 40h, 0FEh    ; MOV DW, FE40h
    DB 0B8h, 07h, 00h    ; MOV AW, 0007h
    DB 0EFh    ; OUT DW, AW
    DB 0E8h, 5Ah, 00h    ; CALL sub_dma
    DB 0BAh, 42h, 0FEh    ; MOV DW, FE42h
    DB 0B8h, 07h, 00h    ; MOV AW, 0007h
    DB 0EFh    ; OUT DW, AW
; ---- window 8: WTC 0800h PMC1 00h RFM ECh sub_dma 
    DB 26h, 0C7h, 06h, 0E8h, 0FFh, 00h, 08h    ; MOV word DS1:[FFE8h], 0800h
    DB 0BAh, 40h, 0FEh    ; MOV DW, FE40h
    DB 0B8h, 08h, 00h    ; MOV AW, 0008h
    DB 0EFh    ; OUT DW, AW
    DB 0E8h, 42h, 00h    ; CALL sub_dma
    DB 0BAh, 42h, 0FEh    ; MOV DW, FE42h
    DB 0B8h, 08h, 00h    ; MOV AW, 0008h
    DB 0EFh    ; OUT DW, AW
; ---- window 9: WTC 2000h PMC1 00h RFM ECh sub_dma 
    DB 26h, 0C7h, 06h, 0E8h, 0FFh, 00h, 20h    ; MOV word DS1:[FFE8h], 2000h
    DB 0BAh, 40h, 0FEh    ; MOV DW, FE40h
    DB 0B8h, 09h, 00h    ; MOV AW, 0009h
    DB 0EFh    ; OUT DW, AW
    DB 0E8h, 2Ah, 00h    ; CALL sub_dma
    DB 0BAh, 42h, 0FEh    ; MOV DW, FE42h
    DB 0B8h, 09h, 00h    ; MOV AW, 0009h
    DB 0EFh    ; OUT DW, AW
    DB 26h, 0C7h, 06h, 0E8h, 0FFh, 0FFh, 0FFh    ; MOV word DS1:[FFE8h], FFFFh
    DB 26h, 0C6h, 06h, 0Ah, 0FFh, 00h    ; MOV byte DS1:[FF0Ah], 00h
    DB 26h, 0C6h, 06h, 0E1h, 0FFh, 0ECh    ; MOV byte DS1:[FFE1h], ECh
    DB 0BAh, 00h, 0FFh    ; MOV DW, FF00h
    DB 0EEh    ; OUT DW, AL
    DB 0F4h    ; HALT
done:
    DB 0EBh, 0FEh    ; BR done
fail:
    DB 0BAh, 02h, 0FFh    ; MOV DW, FF02h
    DB 0EEh    ; OUT DW, AL
    DB 0F4h    ; HALT
fspin:
    DB 0EBh, 0FEh    ; BR fspin
kret:
    DB 0C3h    ; RET
brk3:
    DB 0CFh    ; RETI
sub_dma:
    DB 26h, 0C6h, 06h, 0ACh, 0FFh, 47h    ; MOV byte DS1:[FFACh], 47h
    DB 26h, 0C7h, 06h, 00h, 0FEh, 0FEh, 0Fh    ; MOV word DS1:[FE00h], 0FFEh
    DB 26h, 0C7h, 06h, 02h, 0FEh, 0FEh, 0Fh    ; MOV word DS1:[FE02h], 0FFEh
    DB 26h, 0C6h, 06h, 05h, 0FEh, 3Fh    ; MOV byte DS1:[FE05h], 3Fh
    DB 26h, 0C6h, 06h, 04h, 0FEh, 0BFh    ; MOV byte DS1:[FE04h], BFh
    DB 26h, 0C7h, 06h, 06h, 0FEh, 04h, 00h    ; MOV word DS1:[FE06h], 0004h
    DB 26h, 0C6h, 06h, 0A0h, 0FFh, 11h    ; MOV byte DS1:[FFA0h], 11h
    DB 26h, 0C6h, 06h, 0A1h, 0FFh, 8Ch    ; MOV byte DS1:[FFA1h], 8Ch
    DB 0B9h, 28h, 00h    ; MOV CW, 0028h
    DB 0E2h, 0FEh    ; DBNZ $
    DB 26h, 0C6h, 06h, 0A1h, 0FFh, 00h    ; MOV byte DS1:[FFA1h], 00h
    DB 26h, 0C6h, 06h, 0ACh, 0FFh, 47h    ; MOV byte DS1:[FFACh], 47h
    DB 26h, 0C7h, 06h, 00h, 0FEh, 40h, 00h    ; MOV word DS1:[FE00h], 0040h
    DB 26h, 0C7h, 06h, 02h, 0FEh, 0C0h, 0Fh    ; MOV word DS1:[FE02h], 0FC0h
    DB 26h, 0C6h, 06h, 05h, 0FEh, 0A0h    ; MOV byte DS1:[FE05h], A0h
    DB 26h, 0C6h, 06h, 04h, 0FEh, 1Fh    ; MOV byte DS1:[FE04h], 1Fh
    DB 26h, 0C7h, 06h, 06h, 0FEh, 04h, 00h    ; MOV word DS1:[FE06h], 0004h
    DB 26h, 0C6h, 06h, 0A0h, 0FFh, 11h    ; MOV byte DS1:[FFA0h], 11h
    DB 26h, 0C6h, 06h, 0A1h, 0FFh, 8Ch    ; MOV byte DS1:[FFA1h], 8Ch
    DB 0B9h, 28h, 00h    ; MOV CW, 0028h
    DB 0E2h, 0FEh    ; DBNZ $
    DB 26h, 0C6h, 06h, 0A1h, 0FFh, 00h    ; MOV byte DS1:[FFA1h], 00h
    DB 0C3h    ; RET
